CREATE OR REPLACE PROCEDURE public.sp_update_child(IN p_id uuid, IN p_tenant_id uuid, IN p_first_name character varying, IN p_last_name character varying, IN p_date_of_birth date, IN p_classroom_id uuid, IN p_photo_url text, IN p_profile_completion_percentage integer, IN p_enrollment_status character varying, IN p_draft_data text, IN p_is_active boolean, IN p_updated_at timestamp with time zone)  LANGUAGE plpgsql AS $procedure$ BEGIN     UPDATE children     SET first_name = p_first_name,         last_name = p_last_name,         date_of_birth = p_date_of_birth,         classroom_id = p_classroom_id,         photo_url = p_photo_url,         profile_completion_percentage = p_profile_completion_percentage,         enrollment_status = p_enrollment_status,         draft_data = p_draft_data,         is_active = p_is_active,         updated_at = p_updated_at     WHERE id = p_id AND tenant_id = p_tenant_id; END; $procedure$ ;
